import './realtor-runtime-20261019.mjs';import fs from 'node:fs/promises';const{db}=await import('./reply-runtime-20261015.mjs');const dir='artifacts/realtor-final111-20261019';const plan=JSON.parse(await fs.readFile(dir+'/plan.json'));if(plan.ready!==111||Date.parse(plan.at)<Date.now()-10*60000)throw Error('Plan stale/held');const lock=await fs.open(dir+'/release-attempt.json','wx');await lock.writeFile(JSON.stringify({at:new Date().toISOString(),state:'reserved_no_blind_retry'}));await lock.close();const old=plan.plans.filter(p=>p.old_job_id),fresh=plan.plans.filter(p=>!p.old_job_id);const ids='in.('+fresh.map(p=>p.contact_id).join(',')+')';const changed=await db('market_contacts',{id:ids,sequence_paused:'eq.true',sequence_paused_reason:'eq.gta_launch_review',do_not_contact:'eq.false',cross_channel_suppressed_at:'is.null',last_inbound_at:'is.null',last_touch_at:'is.null'},'PATCH',{sequence_paused:false,sequence_paused_reason:null});if(changed.length!==65)throw Error('Partial release inspect');
const start=Date.now()+60000;const rows=fresh.map((p,i)=>({...p,scheduled_at:new Date(start+i*6000).toISOString()}));const receipt=await db('rpc/enqueue_prepared_sms',{},'POST',{p_campaign_key:'gta-20261019-final111',p_name:'GTA final verified pool — October 19',p_rows:rows,p_daily_cap:111});await fs.writeFile(dir+'/fresh-queue-receipt.json',JSON.stringify(receipt,null,2));if(receipt.jobs?.length!==65||receipt.jobs.some(j=>j.replay))throw Error('Unexpected fresh receipt');
const [campaign]=await db('market_campaigns',{id:'eq.'+receipt.campaign_id,select:'id,notes'});const config={...JSON.parse(campaign.notes),startHour:10,endHour:17};await db('market_campaigns',{id:'eq.'+campaign.id},'PATCH',{notes:JSON.stringify(config)});
const restored=[];for(const [i,p]of old.entries()){const[c]=await db('market_contacts',{id:'eq.'+p.contact_id});const[touches,reservations]=await Promise.all([db('market_touches',{contact_id:'eq.'+p.contact_id,select:'id',limit:'1'}),db('partnership_action_reservations',{contact_id:'eq.'+p.contact_id,select:'action_key',limit:'1'})]);if(c.do_not_contact||c.cross_channel_suppressed_at||c.sequence_paused||c.last_inbound_at||c.last_touch_at||c.phone!==p.phone||touches.length||reservations.length)throw Error('Old recipient changed '+p.contact_id);const[j]=await db('sequence_jobs',{id:'eq.'+p.old_job_id,status:'eq.'+p.old_status,provider_sid:'is.null',last_error:'eq.'+p.old_last_error},'PATCH',{status:'pending',error:null,last_error:null,scheduled_at:new Date(start+i*6000).toISOString(),locked_at:null});if(!j)throw Error('Old job changed');restored.push({id:j.id,contact_id:p.contact_id});await fs.appendFile(dir+'/restored.jsonl',JSON.stringify({at:new Date().toISOString(),id:j.id,contact_id:p.contact_id,previous_status:p.old_status,previous_error:p.old_last_error,reason:'Owner authorized final 111; fresh zero touch/reservation and no provider ID; no previous provider attempt.'})+'\n');}
const all=[...receipt.jobs,...restored];await fs.writeFile(dir+'/job-ids.json',JSON.stringify(all,null,2));const verified=await db('sequence_jobs',{id:'in.('+all.map(j=>j.id).join(',')+')',select:'id,contact_id,status,sms_payload,provider_sid',limit:'200'});if(verified.length!==111||verified.some(j=>{const p=plan.plans.find(p=>p.contact_id===j.contact_id);return !p||j.sms_payload.to!==p.phone||j.sms_payload.body!==p.body||j.sms_payload.from!==p.sender}))throw Error('Payload mismatch');await fs.writeFile(dir+'/release-verified.json',JSON.stringify({at:new Date().toISOString(),count:verified.length,rows:verified},null,2));console.log(JSON.stringify({queued:111,new:65,recovered:46}));
